INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('geometria','Geometría','Áreas, perímetros y volúmenes de figuras comunes.','shapes',1);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('topografia','Topografía','Pendientes, distancias, azimut, coordenadas y nivelación.','compass',2);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('concreto','Concreto','Volúmenes de elementos y cantidades de materiales.','cube',3);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('hidraulica','Hidráulica','Caudal, velocidad, Manning y relaciones básicas.','droplet',4);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('estructuras','Estructuras','Herramientas educativas de análisis estructural básico.','building',5);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('metrados','Metrados','Concreto, acero, muros, pisos y encofrado por elemento.','list',6);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('conversor','Conversor','Conversión precisa entre unidades de ingeniería.','swap',7);
INSERT INTO categories (slug,name,description,icon,sort_order) VALUES ('calculadora','Calculadora','Calculadora científica con historial.','calc',8);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'rectangulo','Rectángulo','Área y perímetro de un rectángulo.','calculator','{"inputs": [{"key": "b", "label": "Base", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}, {"key": "h", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "b*h", "unit": "m²", "decimals": 4, "formula": "A = b · h"}, {"key": "P", "label": "Perímetro", "expr": "2*(b+h)", "unit": "m", "decimals": 4, "formula": "P = 2 · (b + h)"}]}'::jsonb,FALSE,1);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'cuadrado','Cuadrado','Área, perímetro y diagonal de un cuadrado.','calculator','{"inputs": [{"key": "l", "label": "Lado", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "l^2", "unit": "m²", "decimals": 4, "formula": "A = l²"}, {"key": "P", "label": "Perímetro", "expr": "4*l", "unit": "m", "decimals": 4, "formula": "P = 4 · l"}, {"key": "d", "label": "Diagonal", "expr": "l*sqrt(2)", "unit": "m", "decimals": 4, "formula": "d = l · √2"}]}'::jsonb,FALSE,2);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'triangulo','Triángulo (base y altura)','Área de un triángulo a partir de su base y altura.','calculator','{"inputs": [{"key": "b", "label": "Base", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}, {"key": "h", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "b*h/2", "unit": "m²", "decimals": 4, "formula": "A = b · h / 2"}]}'::jsonb,FALSE,3);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'triangulo-heron','Triángulo (tres lados)','Área y perímetro con la fórmula de Herón.','calculator','{"inputs": [{"key": "a", "label": "Lado a", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 3, "positive": true}, {"key": "b", "label": "Lado b", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "c", "label": "Lado c", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "sqrt(((a+b+c)/2)*((a+b+c)/2-a)*((a+b+c)/2-b)*((a+b+c)/2-c))", "unit": "m²", "decimals": 4, "formula": "A = √(s·(s−a)·(s−b)·(s−c)),  s = (a+b+c)/2"}, {"key": "P", "label": "Perímetro", "expr": "a+b+c", "unit": "m", "decimals": 4, "formula": "P = a + b + c"}], "invalid_message": "Los tres lados no forman un triángulo válido (cada lado debe ser menor que la suma de los otros dos)."}'::jsonb,FALSE,4);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'circulo','Círculo','Área, circunferencia y diámetro a partir del radio.','calculator','{"inputs": [{"key": "r", "label": "Radio", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "pi*r^2", "unit": "m²", "decimals": 4, "formula": "A = π · r²"}, {"key": "C", "label": "Circunferencia", "expr": "2*pi*r", "unit": "m", "decimals": 4, "formula": "C = 2 · π · r"}, {"key": "D", "label": "Diámetro", "expr": "2*r", "unit": "m", "decimals": 4, "formula": "D = 2 · r"}]}'::jsonb,FALSE,5);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'trapecio','Trapecio','Área de un trapecio.','calculator','{"inputs": [{"key": "B", "label": "Base mayor", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "bm", "label": "Base menor", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2, "positive": true}, {"key": "h", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "(B+bm)/2*h", "unit": "m²", "decimals": 4, "formula": "A = (B + b) / 2 · h"}]}'::jsonb,FALSE,6);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'cilindro','Cilindro','Volumen y áreas de un cilindro.','calculator','{"inputs": [{"key": "r", "label": "Radio", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}, {"key": "h", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "pi*r^2*h", "unit": "m³", "decimals": 4, "formula": "V = π · r² · h"}, {"key": "Al", "label": "Área lateral", "expr": "2*pi*r*h", "unit": "m²", "decimals": 4, "formula": "Aₗ = 2 · π · r · h"}, {"key": "At", "label": "Área total", "expr": "2*pi*r*(r+h)", "unit": "m²", "decimals": 4, "formula": "Aₜ = 2 · π · r · (r + h)"}]}'::jsonb,FALSE,7);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'prisma','Prisma rectangular','Volumen y área total de un prisma rectangular.','calculator','{"inputs": [{"key": "l", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2, "positive": true}, {"key": "a", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}, {"key": "h", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "l*a*h", "unit": "m³", "decimals": 4, "formula": "V = l · a · h"}, {"key": "At", "label": "Área total", "expr": "2*(l*a+l*h+a*h)", "unit": "m²", "decimals": 4, "formula": "Aₜ = 2 · (l·a + l·h + a·h)"}]}'::jsonb,FALSE,8);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'esfera','Esfera','Volumen y área superficial de una esfera.','calculator','{"inputs": [{"key": "r", "label": "Radio", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "4/3*pi*r^3", "unit": "m³", "decimals": 4, "formula": "V = 4/3 · π · r³"}, {"key": "A", "label": "Área superficial", "expr": "4*pi*r^2", "unit": "m²", "decimals": 4, "formula": "A = 4 · π · r²"}]}'::jsonb,FALSE,9);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='geometria'),'cono','Cono','Volumen, generatriz y área lateral de un cono.','calculator','{"inputs": [{"key": "r", "label": "Radio", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1, "positive": true}, {"key": "h", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "pi*r^2*h/3", "unit": "m³", "decimals": 4, "formula": "V = π · r² · h / 3"}, {"key": "g", "label": "Generatriz", "expr": "sqrt(r^2+h^2)", "unit": "m", "decimals": 4, "formula": "g = √(r² + h²)"}, {"key": "Al", "label": "Área lateral", "expr": "pi*r*sqrt(r^2+h^2)", "unit": "m²", "decimals": 4, "formula": "Aₗ = π · r · g"}]}'::jsonb,FALSE,10);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'pendiente','Pendiente','Pendiente entre dos puntos a partir del desnivel y la distancia horizontal.','calculator','{"inputs": [{"key": "dh", "label": "Desnivel (Δh)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2}, {"key": "dx", "label": "Distancia horizontal (Δx)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 20, "positive": true}], "outputs": [{"key": "m", "label": "Pendiente", "expr": "dh/dx", "unit": "m/m", "decimals": 4, "formula": "m = Δh / Δx"}, {"key": "pct", "label": "Pendiente en porcentaje", "expr": "100*dh/dx", "unit": "%", "decimals": 2, "formula": "p = 100 · Δh / Δx"}, {"key": "ang", "label": "Ángulo", "expr": "deg(atan(dh/dx))", "unit": "°", "decimals": 3, "formula": "α = arctan(Δh / Δx)"}]}'::jsonb,FALSE,11);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'pendiente-porcentaje','Pendiente (%) a ángulo','Convierte una pendiente en porcentaje a ángulo y razón.','calculator','{"inputs": [{"key": "p", "label": "Pendiente", "unit": "%", "default": 10}], "outputs": [{"key": "m", "label": "Pendiente", "expr": "p/100", "unit": "m/m", "decimals": 4, "formula": "m = p / 100"}, {"key": "ang", "label": "Ángulo", "expr": "deg(atan(p/100))", "unit": "°", "decimals": 3, "formula": "α = arctan(p / 100)"}]}'::jsonb,FALSE,12);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'diferencia-altura','Diferencia de altura','Desnivel a partir de la distancia inclinada y el ángulo de elevación.','calculator','{"inputs": [{"key": "d", "label": "Distancia inclinada", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 50, "positive": true}, {"key": "ang", "label": "Ángulo de elevación", "units": [["°", 1], ["rad", 57.29577951308232], ["gon", 0.9]], "default": 10}], "outputs": [{"key": "dh", "label": "Diferencia de altura", "expr": "d*sin(rad(ang))", "unit": "m", "decimals": 4, "formula": "Δh = d · sen(α)"}]}'::jsonb,FALSE,13);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'distancia-horizontal','Distancia horizontal','Reduce una distancia inclinada a horizontal.','calculator','{"inputs": [{"key": "d", "label": "Distancia inclinada", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 50, "positive": true}, {"key": "ang", "label": "Ángulo de elevación", "units": [["°", 1], ["rad", 57.29577951308232], ["gon", 0.9]], "default": 10}], "outputs": [{"key": "dx", "label": "Distancia horizontal", "expr": "d*cos(rad(ang))", "unit": "m", "decimals": 4, "formula": "Δx = d · cos(α)"}]}'::jsonb,FALSE,14);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'distancia-inclinada','Distancia inclinada','Distancia inclinada a partir de Δx y Δh.','calculator','{"inputs": [{"key": "dx", "label": "Distancia horizontal (Δx)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 20, "positive": true}, {"key": "dh", "label": "Desnivel (Δh)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2}], "outputs": [{"key": "d", "label": "Distancia inclinada", "expr": "sqrt(dx^2+dh^2)", "unit": "m", "decimals": 4, "formula": "d = √(Δx² + Δh²)"}, {"key": "ang", "label": "Ángulo", "expr": "deg(atan(dh/dx))", "unit": "°", "decimals": 3, "formula": "α = arctan(Δh / Δx)"}]}'::jsonb,FALSE,15);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'distancia-puntos','Distancia entre puntos','Distancia horizontal entre dos puntos con coordenadas (E, N).','calculator','{"inputs": [{"key": "x1", "label": "Este punto 1 (E₁)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0}, {"key": "y1", "label": "Norte punto 1 (N₁)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0}, {"key": "x2", "label": "Este punto 2 (E₂)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 30}, {"key": "y2", "label": "Norte punto 2 (N₂)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 40}], "outputs": [{"key": "d", "label": "Distancia", "expr": "sqrt((x2-x1)^2+(y2-y1)^2)", "unit": "m", "decimals": 4, "formula": "d = √((E₂−E₁)² + (N₂−N₁)²)"}, {"key": "dE", "label": "ΔE", "expr": "x2-x1", "unit": "m", "decimals": 4, "formula": "ΔE = E₂ − E₁"}, {"key": "dN", "label": "ΔN", "expr": "y2-y1", "unit": "m", "decimals": 4, "formula": "ΔN = N₂ − N₁"}]}'::jsonb,FALSE,16);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'coordenadas','Coordenadas de un punto','Calcula (E, N) de un punto desde un punto conocido, distancia y azimut.','calculator','{"inputs": [{"key": "e1", "label": "Este conocido (E₁)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 500000}, {"key": "n1", "label": "Norte conocido (N₁)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 8000000}, {"key": "d", "label": "Distancia", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 100, "positive": true}, {"key": "az", "label": "Azimut", "units": [["°", 1], ["rad", 57.29577951308232], ["gon", 0.9]], "default": 45}], "outputs": [{"key": "e2", "label": "Este (E₂)", "expr": "e1+d*sin(rad(az))", "unit": "m", "decimals": 3, "formula": "E₂ = E₁ + d · sen(Az)"}, {"key": "n2", "label": "Norte (N₂)", "expr": "n1+d*cos(rad(az))", "unit": "m", "decimals": 3, "formula": "N₂ = N₁ + d · cos(Az)"}]}'::jsonb,FALSE,17);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'azimut','Azimut entre puntos','Azimut y distancia de P1 a P2 a partir de sus coordenadas.','calculator','{"inputs": [{"key": "x1", "label": "Este punto 1 (E₁)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0}, {"key": "y1", "label": "Norte punto 1 (N₁)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0}, {"key": "x2", "label": "Este punto 2 (E₂)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 30}, {"key": "y2", "label": "Norte punto 2 (N₂)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 40}], "outputs": [{"key": "az", "label": "Azimut", "expr": "mod(deg(atan2(x2-x1,y2-y1)),360)", "unit": "°", "decimals": 4, "formula": "Az = arctan2(ΔE, ΔN)  (0° a 360°)"}, {"key": "d", "label": "Distancia", "expr": "sqrt((x2-x1)^2+(y2-y1)^2)", "unit": "m", "decimals": 4, "formula": "d = √(ΔE² + ΔN²)"}], "invalid_message": "Los dos puntos son iguales: no se puede definir un azimut."}'::jsonb,FALSE,18);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'angulos','Ángulo entre alineaciones','Ángulo entre dos azimuts.','calculator','{"inputs": [{"key": "az1", "label": "Azimut 1", "units": [["°", 1], ["rad", 57.29577951308232], ["gon", 0.9]], "default": 30}, {"key": "az2", "label": "Azimut 2", "units": [["°", 1], ["rad", 57.29577951308232], ["gon", 0.9]], "default": 120}], "outputs": [{"key": "a", "label": "Ángulo (sentido horario)", "expr": "mod(az2-az1,360)", "unit": "°", "decimals": 4, "formula": "θ = (Az₂ − Az₁) mod 360°"}, {"key": "m", "label": "Ángulo menor", "expr": "min(mod(az2-az1,360),360-mod(az2-az1,360))", "unit": "°", "decimals": 4, "formula": "θ_menor = mín(θ, 360° − θ)"}]}'::jsonb,FALSE,19);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'grados-radianes','Grados, radianes y gradianes','Convierte un ángulo en grados decimales a radianes, gradianes y G° M'' S''''.','calculator','{"inputs": [{"key": "g", "label": "Ángulo en grados decimales", "unit": "°", "default": 45.5, "nonnegative": true}], "outputs": [{"key": "r", "label": "Radianes", "expr": "rad(g)", "unit": "rad", "decimals": 6, "formula": "rad = g · π / 180"}, {"key": "gon", "label": "Gradianes", "expr": "g*10/9", "unit": "gon", "decimals": 4, "formula": "gon = g · 10 / 9"}, {"key": "gd", "label": "Grados", "expr": "floor(g)", "unit": "°", "decimals": 0}, {"key": "mn", "label": "Minutos", "expr": "floor((g-floor(g))*60)", "unit": "''", "decimals": 0}, {"key": "sg", "label": "Segundos", "expr": "((g-floor(g))*60-floor((g-floor(g))*60))*60", "unit": "''''", "decimals": 2}]}'::jsonb,FALSE,20);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),'nivelacion','Nivelación geométrica','Altura del instrumento y cota de un punto con lecturas de mira.','calculator','{"inputs": [{"key": "cota", "label": "Cota del BM", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 100}, {"key": "la", "label": "Lectura atrás (+)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1.5, "nonnegative": true}, {"key": "lv", "label": "Lectura adelante (−)", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.8, "nonnegative": true}], "outputs": [{"key": "hi", "label": "Altura del instrumento", "expr": "cota+la", "unit": "m", "decimals": 3, "formula": "HI = Cota BM + L. atrás"}, {"key": "cp", "label": "Cota del punto", "expr": "cota+la-lv", "unit": "m", "decimals": 3, "formula": "Cota = HI − L. adelante"}, {"key": "dz", "label": "Desnivel", "expr": "la-lv", "unit": "m", "decimals": 3, "formula": "Δz = L. atrás − L. adelante"}]}'::jsonb,FALSE,21);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='concreto'),'losa','Volumen de losa','Volumen de concreto de una losa, con porcentaje de desperdicio.','calculator','{"inputs": [{"key": "L", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}, {"key": "a", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "e", "label": "Espesor", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.2, "positive": true}, {"key": "desp", "label": "Desperdicio", "unit": "%", "default": 5, "nonnegative": true}], "outputs": [{"key": "V", "label": "Volumen neto", "expr": "L*a*e", "unit": "m³", "decimals": 3, "formula": "V = L · a · e"}, {"key": "Vt", "label": "Volumen con desperdicio", "expr": "L*a*e*(1+desp/100)", "unit": "m³", "decimals": 3, "formula": "Vₜ = V · (1 + desperdicio/100)"}]}'::jsonb,FALSE,22);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='concreto'),'columna','Volumen de columna','Volumen de columnas rectangulares.','calculator','{"inputs": [{"key": "b", "label": "Lado b", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.3, "positive": true}, {"key": "h", "label": "Lado h", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.4, "positive": true}, {"key": "H", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 3, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "b*h*H*n", "unit": "m³", "decimals": 3, "formula": "V = b · h · H · n"}]}'::jsonb,FALSE,23);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='concreto'),'columna-circular','Volumen de columna circular','Volumen de columnas circulares.','calculator','{"inputs": [{"key": "D", "label": "Diámetro", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.4, "positive": true}, {"key": "H", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 3, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "pi*D^2/4*H*n", "unit": "m³", "decimals": 3, "formula": "V = π · D² / 4 · H · n"}]}'::jsonb,FALSE,24);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='concreto'),'viga','Volumen de viga','Volumen de vigas rectangulares.','calculator','{"inputs": [{"key": "b", "label": "Ancho b", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.25, "positive": true}, {"key": "h", "label": "Peralte h", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.5, "positive": true}, {"key": "L", "label": "Longitud", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "b*h*L*n", "unit": "m³", "decimals": 3, "formula": "V = b · h · L · n"}]}'::jsonb,FALSE,25);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='concreto'),'zapata','Volumen de zapata','Volumen de zapatas aisladas rectangulares.','calculator','{"inputs": [{"key": "L", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1.5, "positive": true}, {"key": "B", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1.5, "positive": true}, {"key": "h", "label": "Peralte", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.6, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "L*B*h*n", "unit": "m³", "decimals": 3, "formula": "V = L · B · h · n"}]}'::jsonb,FALSE,26);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='concreto'),'cantidades','Cantidades de materiales','Materiales aproximados para un volumen de concreto. Los rendimientos por m³ son editables.','calculator','{"inputs": [{"key": "V", "label": "Volumen de concreto", "units": [["m³", 1], ["L", 0.001], ["cm³", 1e-06], ["ft³", 0.028316846592]], "default": 1, "positive": true}, {"key": "bol", "label": "Cemento por m³", "unit": "bolsas/m³", "default": 9.73, "positive": true, "hint": "Valor referencial; depende de la dosificación."}, {"key": "ar", "label": "Arena por m³", "unit": "m³/m³", "default": 0.52, "positive": true}, {"key": "pi", "label": "Piedra por m³", "unit": "m³/m³", "default": 0.53, "positive": true}, {"key": "ag", "label": "Agua por m³", "unit": "m³/m³", "default": 0.186, "positive": true}], "outputs": [{"key": "c", "label": "Cemento", "expr": "V*bol", "unit": "bolsas", "decimals": 1, "formula": "Cemento = V · bolsas/m³"}, {"key": "a", "label": "Arena", "expr": "V*ar", "unit": "m³", "decimals": 3}, {"key": "p", "label": "Piedra", "expr": "V*pi", "unit": "m³", "decimals": 3}, {"key": "w", "label": "Agua", "expr": "V*ag*1000", "unit": "L", "decimals": 0}]}'::jsonb,TRUE,27);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='hidraulica'),'caudal','Caudal (Q = A · v)','Caudal a partir del área y la velocidad.','calculator','{"inputs": [{"key": "A", "label": "Área de flujo", "units": [["m²", 1], ["cm²", 0.0001], ["ha", 10000.0], ["ft²", 0.09290304]], "default": 0.1, "positive": true}, {"key": "v", "label": "Velocidad", "units": [["m/s", 1], ["cm/s", 0.01], ["km/h", 0.2777777777777778], ["ft/s", 0.3048]], "default": 1.5, "positive": true}], "outputs": [{"key": "Q", "label": "Caudal", "expr": "A*v", "unit": "m³/s", "decimals": 5, "formula": "Q = A · v"}, {"key": "QL", "label": "Caudal", "expr": "A*v*1000", "unit": "L/s", "decimals": 2}]}'::jsonb,FALSE,28);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='hidraulica'),'velocidad','Velocidad (v = Q / A)','Velocidad media a partir del caudal y el área.','calculator','{"inputs": [{"key": "Q", "label": "Caudal", "units": [["m³/s", 1], ["L/s", 0.001], ["m³/h", 0.0002777777777777778]], "default": 0.05, "positive": true}, {"key": "A", "label": "Área de flujo", "units": [["m²", 1], ["cm²", 0.0001], ["ha", 10000.0], ["ft²", 0.09290304]], "default": 0.1, "positive": true}], "outputs": [{"key": "v", "label": "Velocidad", "expr": "Q/A", "unit": "m/s", "decimals": 4, "formula": "v = Q / A"}]}'::jsonb,FALSE,29);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='hidraulica'),'area-tuberia','Sección de tubería llena','Área, perímetro mojado y radio hidráulico de una tubería a sección llena.','calculator','{"inputs": [{"key": "D", "label": "Diámetro interior", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.2, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "pi*D^2/4", "unit": "m²", "decimals": 5, "formula": "A = π · D² / 4"}, {"key": "P", "label": "Perímetro mojado", "expr": "pi*D", "unit": "m", "decimals": 4, "formula": "P = π · D"}, {"key": "R", "label": "Radio hidráulico", "expr": "D/4", "unit": "m", "decimals": 4, "formula": "R = A / P = D / 4"}]}'::jsonb,FALSE,30);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='hidraulica'),'caudal-volumen','Caudal por volumen y tiempo','Caudal a partir de un volumen y el tiempo de llenado.','calculator','{"inputs": [{"key": "V", "label": "Volumen", "units": [["m³", 1], ["L", 0.001], ["cm³", 1e-06], ["ft³", 0.028316846592]], "default": 0.02, "positive": true}, {"key": "t", "label": "Tiempo", "units": [["s", 1], ["min", 60], ["h", 3600]], "default": 10, "positive": true}], "outputs": [{"key": "Q", "label": "Caudal", "expr": "V/t", "unit": "m³/s", "decimals": 6, "formula": "Q = V / t"}, {"key": "QL", "label": "Caudal", "expr": "V/t*1000", "unit": "L/s", "decimals": 3}]}'::jsonb,FALSE,31);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='hidraulica'),'manning','Ecuación de Manning','Velocidad y caudal en flujo a superficie libre.','calculator','{"inputs": [{"key": "n", "label": "Coeficiente de rugosidad n", "default": 0.013, "positive": true}, {"key": "R", "label": "Radio hidráulico", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.1, "positive": true}, {"key": "S", "label": "Pendiente", "unit": "m/m", "default": 0.005, "positive": true}, {"key": "A", "label": "Área mojada", "units": [["m²", 1], ["cm²", 0.0001], ["ha", 10000.0], ["ft²", 0.09290304]], "default": 0.1, "positive": true}], "outputs": [{"key": "v", "label": "Velocidad", "expr": "(1/n)*R^(2/3)*S^(1/2)", "unit": "m/s", "decimals": 4, "formula": "v = (1/n) · R^(2/3) · S^(1/2)"}, {"key": "Q", "label": "Caudal", "expr": "A*(1/n)*R^(2/3)*S^(1/2)", "unit": "m³/s", "decimals": 5, "formula": "Q = A · v"}]}'::jsonb,FALSE,32);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='hidraulica'),'reynolds','Número de Reynolds','Régimen de flujo en tuberías.','calculator','{"inputs": [{"key": "rho", "label": "Densidad", "unit": "kg/m³", "default": 1000, "positive": true}, {"key": "v", "label": "Velocidad", "units": [["m/s", 1], ["cm/s", 0.01], ["km/h", 0.2777777777777778], ["ft/s", 0.3048]], "default": 1, "positive": true}, {"key": "D", "label": "Diámetro", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.1, "positive": true}, {"key": "mu", "label": "Viscosidad dinámica", "unit": "Pa·s", "default": 0.001, "positive": true}], "outputs": [{"key": "Re", "label": "Número de Reynolds", "expr": "rho*v*D/mu", "unit": "", "decimals": 0, "formula": "Re = ρ · v · D / μ"}]}'::jsonb,FALSE,33);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='estructuras'),'viga-simple-uniforme','Viga simple con carga uniforme','Reacciones y momento máximo de una viga simplemente apoyada.','calculator','{"inputs": [{"key": "w", "label": "Carga uniforme", "unit": "kN/m", "default": 10, "positive": true}, {"key": "L", "label": "Luz", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}], "outputs": [{"key": "R", "label": "Reacción en cada apoyo", "expr": "w*L/2", "unit": "kN", "decimals": 3, "formula": "R = w · L / 2"}, {"key": "M", "label": "Momento máximo", "expr": "w*L^2/8", "unit": "kN·m", "decimals": 3, "formula": "M_máx = w · L² / 8"}]}'::jsonb,TRUE,34);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='estructuras'),'viga-puntual','Viga simple con carga puntual central','Reacciones y momento máximo con una carga al centro.','calculator','{"inputs": [{"key": "P", "label": "Carga puntual", "units": [["kN", 1], ["N", 0.001], ["kgf", 0.00980665], ["tf", 9.80665]], "default": 20, "positive": true}, {"key": "L", "label": "Luz", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}], "outputs": [{"key": "R", "label": "Reacción en cada apoyo", "expr": "P/2", "unit": "kN", "decimals": 3, "formula": "R = P / 2"}, {"key": "M", "label": "Momento máximo", "expr": "P*L/4", "unit": "kN·m", "decimals": 3, "formula": "M_máx = P · L / 4"}]}'::jsonb,TRUE,35);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='estructuras'),'viga-flecha','Flecha en viga simple (carga uniforme)','Deflexión máxima al centro de la luz.','calculator','{"inputs": [{"key": "w", "label": "Carga uniforme", "unit": "kN/m", "default": 10, "positive": true}, {"key": "L", "label": "Luz", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}, {"key": "E", "label": "Módulo de elasticidad", "unit": "GPa", "default": 21, "positive": true}, {"key": "I", "label": "Inercia", "unit": "cm⁴", "default": 40000, "positive": true}], "outputs": [{"key": "d", "label": "Flecha máxima", "expr": "1000*5*w*L^4/(384*E*1e6*I*1e-8)", "unit": "mm", "decimals": 3, "formula": "δ = 5 · w · L⁴ / (384 · E · I)"}]}'::jsonb,TRUE,36);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='estructuras'),'esfuerzo-axial','Esfuerzo axial','Esfuerzo normal σ = P / A.','calculator','{"inputs": [{"key": "P", "label": "Fuerza axial", "units": [["kN", 1], ["N", 0.001], ["kgf", 0.00980665], ["tf", 9.80665]], "default": 100, "positive": true}, {"key": "A", "label": "Área", "units": [["cm²", 1], ["m²", 10000.0], ["mm²", 0.01]], "default": 50, "positive": true}], "outputs": [{"key": "s", "label": "Esfuerzo", "expr": "10*P/A", "unit": "MPa", "decimals": 3, "formula": "σ = P / A"}]}'::jsonb,TRUE,37);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='estructuras'),'propiedades-rectangulo','Propiedades de sección rectangular','Área, inercia y módulo de sección.','calculator','{"inputs": [{"key": "b", "label": "Base b", "units": [["cm", 1], ["m", 100], ["mm", 0.1], ["in", 2.54]], "default": 25, "positive": true}, {"key": "h", "label": "Altura h", "units": [["cm", 1], ["m", 100], ["mm", 0.1], ["in", 2.54]], "default": 50, "positive": true}], "outputs": [{"key": "A", "label": "Área", "expr": "b*h", "unit": "cm²", "decimals": 2, "formula": "A = b · h"}, {"key": "I", "label": "Inercia", "expr": "b*h^3/12", "unit": "cm⁴", "decimals": 1, "formula": "I = b · h³ / 12"}, {"key": "S", "label": "Módulo de sección", "expr": "b*h^2/6", "unit": "cm³", "decimals": 1, "formula": "S = b · h² / 6"}, {"key": "r", "label": "Radio de giro", "expr": "h/sqrt(12)", "unit": "cm", "decimals": 3, "formula": "r = h / √12"}]}'::jsonb,TRUE,38);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-concreto','Concreto (elemento general)','Volumen de concreto de cualquier elemento prismático.','calculator','{"inputs": [{"key": "L", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 3, "positive": true}, {"key": "a", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.3, "positive": true}, {"key": "h", "label": "Alto", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.3, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 1, "positive": true}], "outputs": [{"key": "V", "label": "Volumen", "expr": "L*a*h*n", "unit": "m³", "decimals": 3, "formula": "V = L · a · h · n"}]}'::jsonb,FALSE,39);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-acero','Acero de refuerzo','Peso de barras corrugadas con P = d² / 162 (kg/m, d en mm).','calculator','{"inputs": [{"key": "d", "label": "Diámetro de barra", "units": [["mm", 1], ["pulg", 25.4]], "default": 12, "positive": true}, {"key": "L", "label": "Longitud por barra", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 6, "positive": true}, {"key": "n", "label": "Cantidad de barras", "unit": "und", "default": 10, "positive": true}], "outputs": [{"key": "p", "label": "Peso por metro", "expr": "d^2/162", "unit": "kg/m", "decimals": 3, "formula": "p = d² / 162"}, {"key": "Lt", "label": "Longitud total", "expr": "L*n", "unit": "m", "decimals": 2}, {"key": "W", "label": "Peso total", "expr": "d^2/162*L*n", "unit": "kg", "decimals": 2, "formula": "W = p · L · n"}]}'::jsonb,FALSE,40);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-muros','Muros de albañilería','Área neta, volumen y unidades de ladrillo.','calculator','{"inputs": [{"key": "L", "label": "Longitud", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}, {"key": "H", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 2.4, "positive": true}, {"key": "t", "label": "Espesor", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.15, "positive": true}, {"key": "hu", "label": "Área de vanos", "units": [["m²", 1], ["cm²", 0.0001], ["ha", 10000.0], ["ft²", 0.09290304]], "default": 0, "nonnegative": true}, {"key": "u", "label": "Ladrillos por m²", "unit": "und/m²", "default": 39, "positive": true, "hint": "Referencial: depende del aparejo y la unidad."}], "outputs": [{"key": "Ab", "label": "Área bruta", "expr": "L*H", "unit": "m²", "decimals": 2, "formula": "A = L · H"}, {"key": "An", "label": "Área neta", "expr": "L*H-hu", "unit": "m²", "decimals": 2, "formula": "Aₙ = A − vanos"}, {"key": "V", "label": "Volumen de muro", "expr": "(L*H-hu)*t", "unit": "m³", "decimals": 3}, {"key": "N", "label": "Ladrillos", "expr": "(L*H-hu)*u", "unit": "und", "decimals": 0, "formula": "N = Aₙ · und/m²"}], "invalid_message": "El área de vanos no puede ser mayor que el área del muro."}'::jsonb,FALSE,41);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-pisos','Pisos y acabados','Área de piso con desperdicio y perímetro para zócalo.','calculator','{"inputs": [{"key": "L", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}, {"key": "a", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "desp", "label": "Desperdicio", "unit": "%", "default": 5, "nonnegative": true}], "outputs": [{"key": "A", "label": "Área", "expr": "L*a", "unit": "m²", "decimals": 2, "formula": "A = L · a"}, {"key": "At", "label": "Área con desperdicio", "expr": "L*a*(1+desp/100)", "unit": "m²", "decimals": 2}, {"key": "P", "label": "Perímetro", "expr": "2*(L+a)", "unit": "m", "decimals": 2}]}'::jsonb,FALSE,42);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-columnas','Columnas','Concreto y encofrado de columnas rectangulares.','calculator','{"inputs": [{"key": "b", "label": "Lado b", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.3, "positive": true}, {"key": "h", "label": "Lado h", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.4, "positive": true}, {"key": "H", "label": "Altura", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 3, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 4, "positive": true}], "outputs": [{"key": "V", "label": "Concreto", "expr": "b*h*H*n", "unit": "m³", "decimals": 3, "formula": "V = b · h · H · n"}, {"key": "E", "label": "Encofrado", "expr": "2*(b+h)*H*n", "unit": "m²", "decimals": 2, "formula": "E = 2 · (b + h) · H · n"}]}'::jsonb,FALSE,43);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-vigas','Vigas','Concreto y encofrado (fondo y dos costados).','calculator','{"inputs": [{"key": "b", "label": "Ancho b", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.25, "positive": true}, {"key": "h", "label": "Peralte h", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.5, "positive": true}, {"key": "L", "label": "Longitud", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 4, "positive": true}], "outputs": [{"key": "V", "label": "Concreto", "expr": "b*h*L*n", "unit": "m³", "decimals": 3, "formula": "V = b · h · L · n"}, {"key": "E", "label": "Encofrado", "expr": "(b+2*h)*L*n", "unit": "m²", "decimals": 2, "formula": "E = (b + 2·h) · L · n"}]}'::jsonb,FALSE,44);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-losas','Losas','Concreto y encofrado de losas macizas.','calculator','{"inputs": [{"key": "L", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 5, "positive": true}, {"key": "a", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 4, "positive": true}, {"key": "e", "label": "Espesor", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.2, "positive": true}], "outputs": [{"key": "V", "label": "Concreto", "expr": "L*a*e", "unit": "m³", "decimals": 3, "formula": "V = L · a · e"}, {"key": "E", "label": "Encofrado", "expr": "L*a", "unit": "m²", "decimals": 2, "formula": "E = L · a"}]}'::jsonb,FALSE,45);
INSERT INTO tools (category_id,slug,name,description,kind,definition,educational_only,sort_order) VALUES ((SELECT id FROM categories WHERE slug='metrados'),'metrado-zapatas','Zapatas','Concreto y excavación de zapatas aisladas.','calculator','{"inputs": [{"key": "L", "label": "Largo", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1.5, "positive": true}, {"key": "B", "label": "Ancho", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1.5, "positive": true}, {"key": "h", "label": "Peralte", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.6, "positive": true}, {"key": "Hx", "label": "Profundidad de excavación", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 1.2, "positive": true}, {"key": "sob", "label": "Sobreancho por lado", "units": [["m", 1], ["cm", 0.01], ["mm", 0.001], ["km", 1000], ["ft", 0.3048], ["in", 0.0254]], "default": 0.1, "nonnegative": true}, {"key": "n", "label": "Cantidad", "unit": "und", "default": 4, "positive": true}], "outputs": [{"key": "V", "label": "Concreto", "expr": "L*B*h*n", "unit": "m³", "decimals": 3, "formula": "V = L · B · h · n"}, {"key": "Ex", "label": "Excavación", "expr": "(L+2*sob)*(B+2*sob)*Hx*n", "unit": "m³", "decimals": 3, "formula": "Vₑ = (L+2s) · (B+2s) · Hₑ · n"}]}'::jsonb,FALSE,46);
