INSERT INTO formulas (category_id,tool_id,slug,name,expression,description,explanation,example,is_featured,sort_order) VALUES ((SELECT id FROM categories WHERE slug='topografia'),(SELECT id FROM tools WHERE slug='pendiente' LIMIT 1),'pendiente','Pendiente','m = Δh / Δx','Relación entre el desnivel y la distancia horizontal entre dos puntos.','Se expresa como razón (m/m) o en porcentaje multiplicando por 100. El signo indica si el terreno sube o baja en el sentido del recorrido.','Δh = 2 m y Δx = 20 m → m = 0,10 = 10 %.',TRUE,1);
